                        # 保底：没有收取到声骸时，重新打开图鉴传送回当前聚落（传送点面朝金色声骸群），再搜索一次
                        self.log_info(self.tr('no echo collected, re-teleport to current nest as fallback'))
                        self.ensure_main(time_out=30)
                        self.openF2Book("gray_book_boss")
